 "content": "def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # identify isolated non-background markers and color line from each to a border cap
    pts=[(r,c,grid[r][c]) for r in range(1,h-1) for c in range(1,w-1) if grid[r][c]!=bg]
    if not pts:return out
    # Background-contrast cap locations indicate projection axes. Strokes at top/bottom => column lines;
    # strokes at left/right => row lines. Each seed line reaches the corresponding edge.
    top=any(v!=bg for v in grid[0]); bottom=any(v!=bg for v in grid[-1])
    left=any(row[0]!=bg for row in grid); right=any(row[-1]!=bg for row in grid)
    for r,c,col in pts:
        if top and bottom:
            for rr in range(1,h-1):
                if (rr,c)!=(r,c):out[rr][c]=col
        elif left and right:
            for cc in range(1,w-1):
                if (r,cc)!=(r,c):out[r][cc]=col
        out[r][c]=4
    return out
